.adm-table-wrap {
          background: #fff;
          border-radius: 14px;
          border: 1px solid #e5e7eb;
          overflow-x: auto;
          -webkit-overflow-scrolling: touch;
          box-shadow: 0 2px 16px rgba(0,0,0,0.06);
        }
@media (max-width: 768px) {
  .adm-table-wrap { overflow-x: hidden; }
  .adm-table-wrap table { width: 100%; table-layout: fixed; }
}

